(()=>{"use strict";const fmt=n=>Number(n).toLocaleString(typeof window<"u"&&window.CMI18n?window.CMI18n.formatLocale:"en-US",{maximumFractionDigits:6}),$=id=>document.getElementById(id),F={kg:1,g:.001,lb:.45359237,oz:.028349523125},UNITS=["kg","g","lb","oz"];function compute(v,from,to){const base=v*F[from],all={};for(const u in F)all[u]=base/F[u];return{result:base/F[to],base,all}}function get(){const v={};return document.querySelectorAll("input,select").forEach(e=>{v[e.id]=e.tagName==="SELECT"?e.value:parseFloat(e.value)}),v}function render(){const v=get();if(!(Number.isFinite(v.val)&&v.val>=0)){$("result").textContent="\u2014",$("chipBase").textContent="\u2014",$("chipInv").textContent="\u2014",$("tblRows").innerHTML="";const vd2=$("verdict");vd2.className="verdict bad",$("verdictText").textContent="Enter a value at zero or above to convert a weight.",window.__summary="";return}const r=compute(v.val,v.from,v.to);$("result").textContent=fmt(r.result)+" "+v.to,$("chipBase").textContent=fmt(r.base)+" kg",$("chipInv").textContent=fmt(compute(1,v.to,v.from).result)+" "+v.from+" per 1 "+v.to;let rh="";for(const u of Object.keys(F))rh+="<tr><td>"+u+"</td><td class='num'>"+fmt(r.all[u])+"</td></tr>";$("tblRows").innerHTML=rh;const vd=$("verdict");vd.className="verdict",$("verdictText").textContent="Same mass, four units \u2014 the table below shows the full conversion.",window.__summary="Conversion: "+fmt(v.val)+" "+v.from+" = "+fmt(r.result)+" "+v.to+"; in kg: "+fmt(r.base)+"."}document.querySelectorAll("input,select").forEach(e=>e.addEventListener("input",render)),render()})();
